<?php
declare(strict_types=1);
require_once __DIR__.'/ChecklistTemplateAssociation.php';

final class ActiveBaselineOperationalCaseConnector
{
    public const VERSION='active-baseline-operational-case-v1';
    public function __construct(private readonly mysqli$db,private readonly string$prefix){if(preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1)throw new InvalidArgumentException('Invalid local prefix');}

    public function inspect(int$legacyObjectId):array
    {
        if($legacyObjectId<1)throw new InvalidArgumentException('Invalid legacy object id');$p=$this->prefix;$s=$this->db->prepare("SELECT b.id baseline_id,b.legacy_object_id,b.contract_version,b.cutover_at,b.content_sha256 baseline_hash,b.payload_json,a.id baseline_association_id,a.effective_at,a.template_snapshot_id,a.template_snapshot_version,a.template_content_sha256,t.snapshot_version,t.valid_from,t.validity_scope,t.content_sha256 template_hash FROM `{$p}fm2_legacy_active_baselines` b LEFT JOIN `{$p}fm2_checklist_template_associations` a ON a.subject_kind='legacy_active_baseline' AND a.subject_id=CAST(b.id AS CHAR) LEFT JOIN `{$p}fm2_checklist_template_snapshots` t ON t.id=a.template_snapshot_id WHERE b.legacy_object_id=? LIMIT 2");$s->bind_param('i',$legacyObjectId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);if(count($rows)!==1)throw new DomainException('ACTIVE_BASELINE_NOT_FOUND');$r=$rows[0];$payload=json_decode((string)$r['payload_json'],true,flags:JSON_THROW_ON_ERROR);$conflicts=[];
        if(!hash_equals((string)$r['baseline_hash'],hash('sha256',(string)$r['payload_json'])))$conflicts[]='BASELINE_HASH_MISMATCH';if(($payload['classification']['category']??null)!=='legacy_active')$conflicts[]='CLASSIFICATION_NOT_ACTIVE';foreach($payload['classification']['quarantineCodes']??[]as$code)$conflicts[]=(string)$code;
        if($r['baseline_association_id']===null)$conflicts[]='TEMPLATE_ASSOCIATION_ABSENT';elseif((string)$r['effective_at']!==(string)$r['cutover_at'])$conflicts[]='TEMPLATE_EFFECTIVE_AT_MISMATCH';if($r['template_snapshot_id']===null)$conflicts[]='TEMPLATE_SNAPSHOT_ABSENT';else{if((string)$r['template_snapshot_version']!==(string)$r['snapshot_version']||!hash_equals((string)$r['template_content_sha256'],(string)$r['template_hash']))$conflicts[]='TEMPLATE_HASH_MISMATCH';if((string)$r['valid_from']>(string)$r['cutover_at']||(string)$r['validity_scope']!=='active_baseline_and_future_native_only')$conflicts[]='TEMPLATE_NOT_VALID_AT_CUTOVER';}
        sort($conflicts,SORT_STRING);return['legacyObjectId'=>$legacyObjectId,'baselineId'=>(int)$r['baseline_id'],'baselineHash'=>(string)$r['baseline_hash'],'cutoverAt'=>(string)$r['cutover_at'],'contractVersion'=>(string)$r['contract_version'],'templateSnapshotId'=>(int)($r['template_snapshot_id']??0),'templateSnapshotVersion'=>(string)($r['template_snapshot_version']??''),'templateContentSha256'=>(string)($r['template_content_sha256']??''),'ready'=>$conflicts===[],'conflictCodes'=>$conflicts];
    }

    public function connect(int$legacyObjectId,bool$apply,string$createdAt):array
    {
        $plan=$this->inspect($legacyObjectId);if(!$plan['ready'])throw new DomainException('ACTIVE_BASELINE_NOT_READY:'.implode(',',$plan['conflictCodes']));$existing=$this->existingCase($legacyObjectId,false);if(!$apply){if($existing!==null)$this->assertCompatible($existing,$plan);return$plan+['mode'=>'dry-run','status'=>$existing===null?'would_create':'already_connected','caseId'=>$existing===null?null:(int)$existing['id']];}
        $this->ensureSchema();$this->db->begin_transaction();try{$existing=$this->existingCase($legacyObjectId,true);if($existing!==null){$this->assertCompatible($existing,$plan);$this->db->commit();return$plan+['mode'=>'apply','status'=>'duplicate','caseId'=>(int)$existing['id']];}
            $state='working';$now=(new DateTimeImmutable($createdAt))->format(DATE_ATOM);$insert=$this->db->prepare("INSERT INTO `{$this->prefix}fm2_installation_cases`(legacy_installation_object_id,process_state,actual_start_date,opened_at,opened_by_user_id,created_at,updated_at,lock_version)VALUES(?, ?,NULL,NULL,NULL,?,?,1)");$insert->bind_param('isss',$legacyObjectId,$state,$now,$now);$insert->execute();$caseId=(int)$insert->insert_id;
            $association=(new ChecklistTemplateAssociationTarget($this->db,$this->prefix))->associate('operational_case',(string)$caseId,(string)$plan['cutoverAt'],(int)$plan['templateSnapshotId'],(string)$plan['templateContentSha256'],(string)$plan['templateSnapshotVersion'],(new DateTimeImmutable($createdAt))->format('Y-m-d H:i:s'));
            $version=self::VERSION;$provenance=$this->db->prepare("INSERT INTO `{$this->prefix}fm2_active_case_provenance`(installation_case_id,legacy_object_id,baseline_id,baseline_sha256,cutover_at,template_snapshot_id,template_snapshot_version,template_content_sha256,connector_version,created_at)VALUES(?,?,?,?,?,?,?,?,?,?)");$baselineId=(int)$plan['baselineId'];$templateId=(int)$plan['templateSnapshotId'];$provenance->bind_param('iiississss',$caseId,$legacyObjectId,$baselineId,$plan['baselineHash'],$plan['cutoverAt'],$templateId,$plan['templateSnapshotVersion'],$plan['templateContentSha256'],$version,$now);$provenance->execute();$this->db->commit();return$plan+['mode'=>'apply','status'=>'created','caseId'=>$caseId,'operationalTemplateAssociationId'=>$association['associationId']];
        }catch(Throwable$error){$this->db->rollback();throw$error;}
    }

    private function ensureSchema():void{$this->db->query("CREATE TABLE IF NOT EXISTS `{$this->prefix}fm2_active_case_provenance`(installation_case_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,legacy_object_id BIGINT UNSIGNED NOT NULL,baseline_id BIGINT UNSIGNED NOT NULL,baseline_sha256 CHAR(64) NOT NULL,cutover_at DATETIME NOT NULL,template_snapshot_id BIGINT UNSIGNED NOT NULL,template_snapshot_version VARCHAR(80) NOT NULL,template_content_sha256 CHAR(64) NOT NULL,connector_version VARCHAR(80) NOT NULL,created_at VARCHAR(40) NOT NULL,UNIQUE KEY uq_legacy_object(legacy_object_id),UNIQUE KEY uq_baseline(baseline_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
    private function existingCase(int$id,bool$lock):?array{$suffix=$lock?' FOR UPDATE':'';$s=$this->db->prepare("SELECT id,process_state,actual_start_date,opened_at FROM `{$this->prefix}fm2_installation_cases` WHERE legacy_installation_object_id=? LIMIT 2{$suffix}");$s->bind_param('i',$id);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);if(count($rows)>1)throw new DomainException('MULTIPLE_OPERATIONAL_CASES');return$rows[0]??null;}
    private function assertCompatible(array$case,array$plan):void{$id=(int)$case['id'];$table=$this->db->real_escape_string($this->prefix.'fm2_active_case_provenance');if((int)$this->db->query("SELECT COUNT(*) n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='{$table}'")->fetch_assoc()['n']!==1)throw new DomainException('EXISTING_OPERATIONAL_CASE_INCOMPATIBLE');$p=$this->db->query("SELECT * FROM `{$this->prefix}fm2_active_case_provenance` WHERE installation_case_id={$id}")->fetch_assoc();$a=$this->db->query("SELECT effective_at,template_snapshot_id,template_snapshot_version,template_content_sha256 FROM `{$this->prefix}fm2_checklist_template_associations` WHERE subject_kind='operational_case' AND subject_id='{$id}' LIMIT 2")->fetch_all(MYSQLI_ASSOC);$ok=(string)$case['process_state']==='working'&&$case['actual_start_date']===null&&$case['opened_at']===null&&is_array($p)&&(int)$p['baseline_id']===(int)$plan['baselineId']&&hash_equals((string)$p['baseline_sha256'],(string)$plan['baselineHash'])&&(string)$p['cutover_at']===(string)$plan['cutoverAt']&&(int)$p['template_snapshot_id']===(int)$plan['templateSnapshotId']&&hash_equals((string)$p['template_content_sha256'],(string)$plan['templateContentSha256'])&&count($a)===1&&(string)$a[0]['effective_at']===(string)$plan['cutoverAt']&&(int)$a[0]['template_snapshot_id']===(int)$plan['templateSnapshotId']&&hash_equals((string)$a[0]['template_content_sha256'],(string)$plan['templateContentSha256']);if(!$ok)throw new DomainException('EXISTING_OPERATIONAL_CASE_INCOMPATIBLE');}
}
